<?php
require_once __DIR__.'/app/lib/Db.php';
$config=require __DIR__.'/app/config.php';
$pdo=Db::pdo();
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function initials($name){$parts=preg_split('/\s+/',trim((string)$name));$out='';foreach(array_slice($parts,0,2) as $x){if($x!==''){$ch=function_exists('mb_substr')?mb_substr($x,0,1):substr($x,0,1);$out.=function_exists('mb_strtoupper')?mb_strtoupper($ch):strtoupper($ch);}}return $out?:'TS';}
function valid_logo($path){if(!$path||!str_starts_with($path,'/media/software/')||str_contains($path,'..'))return null;$full=__DIR__.$path;return is_file($full)?$path:null;}
function label_status($s){return ucwords(str_replace('_',' ',(string)$s));}
function status_class($s){if($s==='supported')return 'ok';if(in_array($s,['partially_supported','enterprise_only','plan_dependent','custom_configuration','addon','third_party_integration'],true))return 'partial';if($s==='not_supported')return 'no';return 'unknown';}
if(!preg_match('#^/integrations/([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
$st=$pdo->prepare('SELECT id,name,slug,description FROM integrations WHERE slug=? LIMIT 1');$st->execute([$m[1]]);$i=$st->fetch();if(!$i){http_response_code(404);exit('Not found');}
$q=$pdo->prepare("SELECT p.id,p.name,p.slug,p.short_description,p.logo_path,p.last_reviewed_at,c.name category,c.slug category_slug,pi.support_status,pi.confidence_score FROM product_integrations pi JOIN products p ON p.id=pi.product_id LEFT JOIN categories c ON c.id=p.category_id WHERE pi.integration_id=? AND p.status='active' ORDER BY CASE pi.support_status WHEN 'supported' THEN 1 WHEN 'enterprise_only' THEN 2 WHEN 'plan_dependent' THEN 2 WHEN 'partially_supported' THEN 2 WHEN 'third_party_integration' THEN 3 WHEN 'not_yet_verified' THEN 4 WHEN 'unknown' THEN 4 WHEN 'not_supported' THEN 5 ELSE 6 END,pi.confidence_score DESC,p.name");$q->execute([$i['id']]);$products=$q->fetchAll();
$counts=['supported'=>0,'conditional'=>0,'unknown'=>0,'not_supported'=>0];$conf=[];foreach($products as $x){$s=$x['support_status'];if($s==='supported')$counts['supported']++;elseif($s==='not_supported')$counts['not_supported']++;elseif(in_array($s,['unknown','not_yet_verified'],true))$counts['unknown']++;else $counts['conditional']++;if(!in_array($s,['unknown','not_yet_verified'],true))$conf[]=(float)$x['confidence_score'];}
$avg=$conf?(int)round(array_sum($conf)/count($conf)*100):0;$desc=$i['description']?:('Compare recorded software support for '.$i['name'].' integration using TechSelectAI evidence-backed data.');$canonical=rtrim($config['site_url'],'/').'/integrations/'.$i['slug'];$items=[];foreach($products as $n=>$x)$items[]=['@type'=>'ListItem','position'=>$n+1,'url'=>rtrim($config['site_url'],'/').'/software/'.$x['slug'],'name'=>$x['name']];$ld=['@context'=>'https://schema.org','@type'=>'ItemList','name'=>$i['name'].' software integrations','itemListElement'=>$items];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($i['name'])?> Integration Software Comparison | TechSelectAI</title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e($canonical)?>"><meta property="og:title" content="<?=e($i['name'])?> Integration Comparison | TechSelectAI"><meta property="og:description" content="<?=e($desc)?>"><meta property="og:url" content="<?=e($canonical)?>"><script type="application/ld+json"><?=json_encode($ld,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><style>:root{--navy:#123b67;--ink:#172033;--muted:#64748b;--line:#e2e8f0;--soft:#f7fafc;--green:#137a55;--greenbg:#e9f8f1;--amber:#95610a;--amberbg:#fff7df;--red:#b42318;--redbg:#fff0ee}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink)}a{color:#145ea8}header{display:flex;justify-content:space-between;align-items:center;padding:17px max(24px,5vw);border-bottom:1px solid var(--line)}header>a{font-size:20px;font-weight:800;color:var(--navy);text-decoration:none}nav a{margin-left:20px;text-decoration:none;font-weight:650;color:#334155}.wrap{max-width:1160px;margin:auto;padding:0 24px}.crumbs{font-size:13px;color:var(--muted);padding-top:25px}.hero{padding:38px 0 20px}.eyebrow{font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:#52708b;font-weight:800}.hero h1{font-size:clamp(36px,5vw,58px);line-height:1.03;margin:8px 0 13px}.lead{font-size:19px;line-height:1.65;color:#536174;max-width:900px}.stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.pill{padding:8px 11px;border-radius:999px;background:#f1f6f9;color:#31516e;font-size:13px;font-weight:700}.section{padding-top:34px}.section h2{font-size:28px;margin:0 0 8px}.intro{color:var(--muted);line-height:1.6}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:15px}table{width:100%;border-collapse:collapse;min-width:820px}th,td{text-align:left;padding:14px;border-bottom:1px solid var(--line);vertical-align:top}th{background:var(--soft);font-size:12px;color:#526071}.product-cell{display:flex;gap:12px;align-items:center}.mark{width:42px;height:42px;border:1px solid #dbe5ec;border-radius:10px;background:#f4f8fa;display:grid;place-items:center;overflow:hidden;color:var(--navy);font-weight:800;flex:0 0 auto}.mark img{width:100%;height:100%;object-fit:contain;padding:5px}.badge{display:inline-block;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.badge.ok{color:var(--green);background:var(--greenbg)}.badge.partial{color:var(--amber);background:var(--amberbg)}.badge.no{color:var(--red);background:var(--redbg)}.badge.unknown{color:#596579;background:#eef2f7}.guide{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.card{border:1px solid var(--line);border-radius:13px;padding:16px;background:#fff}.card h3{font-size:16px;margin:0 0 6px}.card p{margin:0;color:var(--muted);line-height:1.5}.cta{margin:42px 0 0;padding:26px;border-radius:17px;background:linear-gradient(135deg,#f0f8fb,#f5f8fc);border:1px solid #d5e5ed}.btn{display:inline-block;margin-top:8px;padding:11px 16px;border-radius:10px;background:var(--navy);color:#fff;text-decoration:none;font-weight:750}footer{margin:56px 0 30px;color:var(--muted);font-size:13px}@media(max-width:650px){nav{display:none}}</style></head><body><header><a href="/">TechSelectAI</a><nav><a href="/software">Software</a><a href="/methodology">Methodology</a><a href="/">Get Advice</a></nav></header><main class="wrap"><div class="crumbs"><a href="/">Home</a> / Integrations / <?=e($i['name'])?></div><section class="hero"><div class="eyebrow">Integration comparison</div><h1><?=e($i['name'])?></h1><p class="lead"><?=e($desc)?></p><div class="stats"><span class="pill"><?=count($products)?> products tracked</span><span class="pill"><?=$counts['supported']?> supported</span><span class="pill"><?=$counts['conditional']?> conditional</span><span class="pill"><?=$counts['unknown']?> unknown</span><span class="pill"><?=$counts['not_supported']?> not supported</span><?php if($avg):?><span class="pill"><?=$avg?>% avg known-fact confidence</span><?php endif;?></div></section><section class="section"><h2>Product support</h2><p class="intro">This page compares recorded integration support only. A supported integration does not by itself mean the product is the best fit for your company.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Status</th><th>Confidence</th><th>Last reviewed</th></tr></thead><tbody><?php foreach($products as $x):$logo=valid_logo($x['logo_path']);?><tr><td><div class="product-cell"><div class="mark"><?php if($logo):?><img src="<?=e($logo)?>" alt="<?=e($x['name'])?> logo"><?php else:?><?=e(initials($x['name']))?><?php endif;?></div><div><strong><a href="/software/<?=e($x['slug'])?>"><?=e($x['name'])?></a></strong><?php if($x['short_description']):?><div class="intro" style="font-size:12px"><?=e($x['short_description'])?></div><?php endif;?></div></div></td><td><?php if($x['category_slug']):?><a href="/categories/<?=e($x['category_slug'])?>"><?=e($x['category'])?></a><?php else:?>Not recorded<?php endif;?></td><td><span class="badge <?=e(status_class($x['support_status']))?>"><?=e(label_status($x['support_status']))?></span></td><td><?=intval(round(((float)$x['confidence_score'])*100))?>%</td><td><?=e($x['last_reviewed_at']?date('M j, Y',strtotime($x['last_reviewed_at'])):'Not recorded')?></td></tr><?php endforeach;?></tbody></table></div></section><section class="section"><h2>How to read this comparison</h2><div class="guide"><div class="card"><h3>Supported</h3><p>TechSelectAI has evidence that the integration is available.</p></div><div class="card"><h3>Conditional</h3><p>Availability may depend on edition, add-on, connector, configuration or third party.</p></div><div class="card"><h3>Unknown</h3><p>Evidence is incomplete. Unknown does not mean unsupported.</p></div><div class="card"><h3>Not supported</h3><p>Current evidence explicitly indicates the integration is unavailable.</p></div></div></section><section class="cta"><div class="eyebrow">Independent software advice</div><h2>Need <?=e($i['name'])?> integration?</h2><p>Tell TechSelectAI your must-have capabilities, deployment constraints, region, security requirements and budget. Integration fit is evaluated together with the rest of your requirements.</p><a class="btn" href="/?integration=<?=rawurlencode($i['name'])?>">Find suitable software</a></section><footer>TechSelectAI uses evidence-backed product data. Unknown means not yet verified; it does not mean unsupported. Vendor names and trademarks belong to their respective owners.</footer></main></body></html>